def test_dotproduct():
    import vectorops
    res = vectorops.dotproduct([1, 2], [3, 4])
    assert res == 11, f"Expected 11 for dot product of [1,2] and [3,4], got {res}"

if __name__ == "__main__":
    test_dotproduct()
